#include <iostream>
using namespace std;

constexpr long long MOD = 1000000007;

long long modPow(long long base, long long exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    long long factorialN = 1;
    long long factorial2N = 1;

    for (long long i = 1; i <= 2 * n; ++i) {
        factorial2N = factorial2N * (i % MOD) % MOD;
        if (i == n) factorialN = factorial2N;
    }

    long long centralBinomial = factorial2N * modPow(factorialN, MOD - 2) % MOD;
    centralBinomial = centralBinomial * modPow(factorialN, MOD - 2) % MOD;

    cout << (centralBinomial - n % MOD + MOD) % MOD;
    return 0;
}

